public String getReadableJSTypeName(Object obj) {
    // Check if the object is null
    if (obj == null) {
        return "null";
    }

    // Get the class of the object
    Class<?> clazz = obj.getClass();

    // Get the simple name of the class
    String simpleName = clazz.getSimpleName();

    // Check if the simple name is empty
    if (simpleName.isEmpty()) {
        // Get the canonical name of the class
        String canonicalName = clazz.getCanonicalName();

        // Return the canonical name if not null, otherwise return "Object"
        return canonicalName != null ? canonicalName : "Object";
    }

    return simpleName;
}

